steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(first: 50, orderBy: priority) {
        nodes {
          id
          identifier
          title
          description
          priority
          state {
            name
          }
          project {
            id
            name
            description
          }
          dueDate
          team {
            name
          }
          labels {
            nodes {
              name
            }
          }
          issueType {
            name
          }
        }
      }
    }"
  }'
